public struct FfiConverterTypeClientTransactionBuilder: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = ClientTransactionBuilder

    public static func lift(_ handle: UInt64) throws -> ClientTransactionBuilder {
        return ClientTransactionBuilder(unsafeFromHandle: handle)
    }

    public static func lower(_ value: ClientTransactionBuilder) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ClientTransactionBuilder {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: ClientTransactionBuilder, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


