     */
public static func tryFromObject(object: Object)throws  -> Clock  {
    return try  FfiConverterTypeClock_lift(try rustCallWithError(FfiConverterTypeSdkFfiError_lift) {
    uniffi_iota_sdk_ffi_fn_constructor_clock_try_from_object(
        FfiConverterTypeObject_lower(object),$0
    )
})
}
    

    
    /**
     * The object's ID.
     */
open func id() -> ObjectId  {
    return try!  FfiConverterTypeObjectId_lift(try! rustCall() {
    uniffi_iota_sdk_ffi_fn_method_clock_id(
            self.uniffiCloneHandle(),$0
    )
})
}
    
    /**
     * The clock's timestamp (ms), set by consensus every commit.
     */
open func timestampMs() -> UInt64  {
    return try!  FfiConverterUInt64.lift(try! rustCall() {
    uniffi_iota_sdk_ffi_fn_method_clock_timestamp_ms(
            self.uniffiCloneHandle(),$0
    )
