#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeGraphQLClient: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = GraphQlClient

    public static func lift(_ handle: UInt64) throws -> GraphQlClient {
        return GraphQlClient(unsafeFromHandle: handle)
    }

    public static func lower(_ value: GraphQlClient) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> GraphQlClient {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: GraphQlClient, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeGraphQLClient_lift(_ handle: UInt64) throws -> GraphQlClient {
    return try FfiConverterTypeGraphQLClient.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeGraphQLClient_lower(_ value: GraphQlClient) -> UInt64 {
    return FfiConverterTypeGraphQLClient.lower(value)
}






/**
 * A move identifier
 *
 * # BCS
 *
 * The BCS serialized form for this type is defined by the following ABNF:
 *
 * ```text
 * identifier = %d1-128    ; length of the identifier
 * (ALPHA *127(ALPHA / DIGIT / UNDERSCORE)) /
 * (UNDERSCORE 1*127(ALPHA / DIGIT / UNDERSCORE))
 *
 * UNDERSCORE = %x95
 * ```
