// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceTransactionSignerFn {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceTransactionSignerFn = UniffiVTableCallbackInterfaceTransactionSignerFn(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeTransactionSignerFn.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface TransactionSignerFn: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeTransactionSignerFn.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface TransactionSignerFn: handle missing in uniffiClone")
            }
        },
        sign: { (
            uniffiHandle: UInt64,
            transaction: UInt64,
            uniffiFutureCallback: @escaping UniffiForeignFutureCompleteRustBuffer,
            uniffiCallbackData: UInt64,
            uniffiOutDroppedCallback: UnsafeMutablePointer<UniffiForeignFutureDroppedCallbackStruct>
        ) in
            let makeCall = {
                () async throws -> TransactionSignerFnOutput in
                guard let uniffiObj = try? FfiConverterTypeTransactionSignerFn.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try await uniffiObj.sign(
                     transaction: try FfiConverterTypeTransaction_lift(transaction)
                )
            }

            let uniffiHandleSuccess = { (returnValue: TransactionSignerFnOutput) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultRustBuffer(
                        returnValue: FfiConverterTypeTransactionSignerFnOutput_lower(returnValue),
                        callStatus: RustCallStatus()
                    )
                )
            }
            let uniffiHandleError = { (statusCode, errorBuf) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultRustBuffer(
                        returnValue: RustBuffer.empty(),
                        callStatus: RustCallStatus(code: statusCode, errorBuf: errorBuf)
                    )
                )
            }
            uniffiTraitInterfaceCallAsyncWithError(
                makeCall: makeCall,
                handleSuccess: uniffiHandleSuccess,
                handleError: uniffiHandleError,
                lowerError: FfiConverterTypeSdkFfiError_lower,
                droppedCallback: uniffiOutDroppedCallback
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceTransactionSignerFn> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceTransactionSignerFn>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitTransactionSignerFn() {
    uniffi_iota_sdk_ffi_fn_init_callback_vtable_transactionsignerfn(UniffiCallbackInterfaceTransactionSignerFn.vtablePtr)
}

