}

    /**
     * Convert this type to a JSON encoded string.
     */
public func toJson()throws  -> String  {
    return try  FfiConverterString.lift(try rustCallWithError(FfiConverterTypeSdkFfiError_lift) {
    uniffi_iota_sdk_ffi_fn_method_executionerror_to_json(
            FfiConverterTypeExecutionError_lower(self),$0
    )
})
}



}

